const empty: AutoloadActionState = { ok: false, message: "", problem: null, solution: null, warnings: [], layout: null, layoutOffsetX: 0, envelope: null, edition: null, passengerPlan: null };
type GraphicSlot = { key: string; holdId: string; locationRef: string; positions: SolverPosition[] };
type DeckKey = "MAIN" | "LOWER";
type AssignmentRow = { assignment: LoadPlanningAssignment; load: SolverLoad | undefined; position: SolverPosition | undefined };

const slotKey = (position: SolverPosition) => `${position.holdId}|${position.locationRef ?? position.id}`;
const fits = (load: SolverLoad, position: SolverPosition) => load.loadType === position.loadType && load.weightKg <= position.maximumWeightKg && (load.loadType === "BULK" || position.acceptedUldCodes.includes(load.uldCode!)) && (load.loadType !== "BULK" || load.volumeLitres === null || position.maximumVolumeLitres === null || load.volumeLitres <= position.maximumVolumeLitres);
