  const assigned = assignments.map((assignment) => ({ assignment, load: loads.get(assignment.loadId)!, position: positions.get(assignment.positionId)! }));
  const sequencePenalty = assigned.reduce((total, left) => total + assigned.reduce((sum, right) => left.load.unloadOrder < right.load.unloadOrder && left.position.holdId === right.position.holdId && left.position.handlingRank > right.position.handlingRank ? sum + 1 : sum, 0), 0);
